import React from "react";
import {AppBar,Toolbar} from '@mui/material';
import logo from './editor2.png'

    const Header = ()=>{
        return(
           <AppBar>
            <Toolbar>
                <img src={logo} alt="Code Pen" style={{ width: '40px',height:'40px'}}/>
            </Toolbar>
           </AppBar>
        )
    }

export default Header;
